/* @autogenerated */
import { HttpErrorResponse } from '@angular/common/http';
import { HttpClientTestingModule, HttpTestingController } from '@angular/common/http/testing';
import { fakeAsync, TestBed, tick } from '@angular/core/testing';
import { Observable, of } from 'rxjs';
import { ClientService } from './client.service';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { IdentityService } from '@shared/context/identity/identity.service';
import { ErrorService } from '@shared/context/observability/error.service';

describe('ClientService', () => {
  let httpMock: HttpTestingController;
  let token$: Observable<string | null>;
  let config: Record<string, Observable<any>>;

  beforeEach(() => {
    token$ = of('token-123');
    config = { 'data.token-wait-ms': of(undefined), 'data.convert-iso-dates': of(true) };

    const appState = {
      language: of('es'),
    } as unknown as AppStateService;

    const identity = {
      token: jasmine.createSpy('token').and.callFake(() => token$),
    } as unknown as IdentityService;

    const appConfig = { value$: (path: string) => config[path] ?? of(undefined) };

    const errorService = {
      initialiceError: jasmine.createSpy('initialiceError'),
    } as unknown as ErrorService;

    TestBed.configureTestingModule({
      imports: [HttpClientTestingModule],
      providers: [
        ClientService,
        { provide: AppStateService, useValue: appState },
        { provide: IdentityService, useValue: identity },
        { provide: RuntimeConfigService, useValue: appConfig },
        { provide: ErrorService, useValue: errorService },
      ],
    });

    httpMock = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    httpMock.verify();
  });

  it('adds language and authorization headers, converts ISO dates', (done) => {
    const service = TestBed.inject(ClientService);

    service
      .get<{ createdAt: Date }>({
        url: '/api/items',
        identity: 'main',
        withIdentity: false,
      })
      .subscribe((value) => {
        expect(value.createdAt instanceof Date).toBeTrue();
        done();
      });

    const req = httpMock.expectOne('/api/items');
    expect(req.request.headers.get('Accept-Language')).toBe('es');
    expect(req.request.headers.get('Authorization')).toBe('Bearer token-123');

    req.flush({ createdAt: '2020-01-01T00:00:00Z' });
  });

  it('keeps ISO strings by default: the repository converts by metadata', (done) => {
    config['data.convert-iso-dates'] = of(undefined);
    const service = TestBed.inject(ClientService);

    service.get<{ at: string }>({ url: '/api/dates' }).subscribe((value) => {
      expect(value.at).toBe('2025-10-30T12:00:00Z');
      done();
    });

    httpMock.expectOne('/api/dates').flush({ at: '2025-10-30T12:00:00Z' });
  });

  describe('date conversion with data.convert-iso-dates', () => {
    const cases: [string, string, string][] = [
      ['UTC (Z)', '2025-10-30T12:00:00Z', '2025-10-30T12:00:00.000Z'],
      ['offset +0200', '2025-10-30T12:00:00+0200', '2025-10-30T10:00:00.000Z'],
      ['offset +02:00', '2025-10-30T12:00:00+02:00', '2025-10-30T10:00:00.000Z'],
      ['without offset', '2025-10-30T12:00:00', new Date('2025-10-30T12:00:00').toISOString()],
      ['with milliseconds', '2025-10-30T12:00:00.123+02:00', '2025-10-30T10:00:00.123Z'],
    ];

    cases.forEach(([label, raw, iso]) => {
      it(`converts ${label} to Date`, (done) => {
        const service = TestBed.inject(ClientService);

        service.get<{ at: Date }>({ url: '/api/dates' }).subscribe((value) => {
          expect(value.at instanceof Date).toBeTrue();
          expect(value.at.toISOString()).toBe(iso);
          done();
        });

        httpMock.expectOne('/api/dates').flush({ at: raw });
      });
    });

    it('keeps non-date strings untouched', (done) => {
      const service = TestBed.inject(ClientService);

      service.get<{ code: string; day: string }>({ url: '/api/dates' }).subscribe((value) => {
        expect(value.code).toBe('2025-10-30T12');
        expect(value.day).toBe('2025-10-30');
        done();
      });

      httpMock.expectOne('/api/dates').flush({ code: '2025-10-30T12', day: '2025-10-30' });
    });
  });

  describe('without session', () => {
    it('fails with 401 after the default token wait', fakeAsync(() => {
      token$ = new Observable<string | null>((subscriber) => subscriber.next(null));
      const service = TestBed.inject(ClientService);
      let error: HttpErrorResponse | undefined;

      service.get({ url: '/api/items', identity: 'main' }).subscribe({ error: (e) => (error = e) });

      tick(1_999);
      expect(error).toBeUndefined();
      tick(1);
      expect(error?.status).toBe(401);
      expect((error as any).identity).toBe('main');
      expect(TestBed.inject(ErrorService).initialiceError).toHaveBeenCalledWith(error);
      httpMock.expectNone('/api/items');
    }));

    it('tags a 401 from the server with the request identity', (done) => {
      const service = TestBed.inject(ClientService);

      service.get({ url: '/api/items', identity: 'main' }).subscribe({
        error: (error) => {
          expect(error.status).toBe(401);
          expect(error.identity).toBe('main');
          done();
        },
      });

      httpMock.expectOne('/api/items').flush(null, { status: 401, statusText: 'Unauthorized' });
    });

    it('does not tag other errors', (done) => {
      const service = TestBed.inject(ClientService);

      service.get({ url: '/api/items', identity: 'main' }).subscribe({
        error: (error) => {
          expect(error.identity).toBeUndefined();
          done();
        },
      });

      httpMock.expectOne('/api/items').flush(null, { status: 403, statusText: 'Forbidden' });
    });

    it('honours data.token-wait-ms', fakeAsync(() => {
      token$ = new Observable<string | null>((subscriber) => subscriber.next(null));
      config['data.token-wait-ms'] = of(1_000);
      const service = TestBed.inject(ClientService);
      let error: HttpErrorResponse | undefined;

      service.get({ url: '/api/items', identity: 'main' }).subscribe({ error: (e) => (error = e) });

      tick(1_000);
      expect(error?.status).toBe(401);
    }));
  });
});
